let reconciliationPriority='All',reconciliationCategory='All';
// Operational metrics from the current shared demo dataset; not production acceptance evidence.
let reportFilters={from:'',to:'',programme:'All',year:'All'},reportDetail='all',coverageFilter='All';
function reportAccess(){return ['a1','c1','d1','sa1'].includes(uid)?'institution':['f1','fv1'].includes(uid)?'finance':null}
function uniqueBy(items,key){return [...new Map(items.map(x=>[key(x),x])).values()]}
function verifiedActivity(p){return p.activityControl?.state!=='CANCELLED'&&['COMPLETION_VERIFIED','CLOSED','ARCHIVED'].includes(p.state)}
function matchingReportDate(date,filters){return !!date&&(!filters.from||date>=filters.from)&&(!filters.to||date<=filters.to)}
function activityYear(p){return p.planningMetadata?.academicYear||(p.sourceClub?clubPlan(clubById(p.sourceClub),p.clubPlanId)?.year:null)||'Unmapped'}
function reportMatch(p,filters){return matchingReportDate(p.due,filters)&&(filters.programme==='All'||p.programme===filters.programme)&&(filters.year==='All'||activityYear(p)===filters.year)}
function approvedReportItems(filters){const rows=[];for(const p of db.plans||[]){if(!['APPROVED','IN_PROGRESS','COMPLETED'].includes(p.state))continue;if(db.plans.some(x=>x.family===p.family&&x.version>p.version&&['APPROVED','IN_PROGRESS','COMPLETED'].includes(x.state)))continue;for(const i of p.items){if(i.status==='CANCELLED')continue;let a=db.projects.find(a=>a.sourceItem===i.id);if(a?.activityControl?.state==='CANCELLED')continue;let basis={due:i.end,programme:p.programme,planningMetadata:{academicYear:p.year}};if(reportMatch(basis,filters))rows.push({key:'academic:'+i.id,id:i.id,title:i.title,plan:p.id,programme:p.programme,year:p.year,due:i.end,activity:a||null,kind:'Academic plan',department:typeof p.department==='string'?p.department:null})}}
for(const c of db.clubs||[])for(const p of c.plans){if(!isApprovedClubPlan(p)||!latestApprovedRevision(c,p))continue;for(const i of clubItems(p)){if(i.status==='CANCELLED')continue;let a=clubItemActivity(i);if(a?.activityControl?.state==='CANCELLED')continue;let basis={due:i.end,programme:'Cross-programme club activity',planningMetadata:{academicYear:p.year}};if(reportMatch(basis,filters))rows.push({key:'club:'+i.id,id:i.id,title:i.title,plan:p.id,programme:basis.programme,year:p.year,due:i.end,activity:a||null,kind:'Club plan'})}}return uniqueBy(rows,r=>r.key)}
function financeReportRows(filters){let rows=[];for(const c of db.clubs||[])for(const b of c.budgets||[]){let p=db.projects.find(p=>p.id===b.project);if(!p||!reportMatch(p,filters))continue;rows.push({club:c,budget:b,activity:p})}return uniqueBy(rows,r=>r.budget.id)}
function evaluationMetrics(ps){const done=[],waiting=[];for(const p of ps)for(const id of p.members){let r=p.reflections[id],e=p.evaluations[id];if(participantResolution(p,id)||!r?.time)continue;let submitted=Date.parse(r.time);if(!Number.isFinite(submitted))continue;if(e?.final&&e.time){let end=Date.parse(e.time);if(Number.isFinite(end)&&end>=submitted)done.push({activity:p,student:id,hours:(end-submitted)/36e5,submitted:r.time,finalized:e.time})}else if(activityControlActive(p)&&['REFLECTION_PENDING','EVALUATION_PENDING'].includes(p.state))waiting.push({activity:p,student:id,submitted:r.time})}return {done,waiting,meanHours:done.length?done.reduce((n,r)=>n+r.hours,0)/done.length:null}}
function reportSnapshot(filters=reportFilters){const access=reportAccess();if(!access)return null;const ps=access==='institution'?uniqueBy(visible().filter(p=>reportMatch(p,filters)),p=>p.id):[];let verified=ps.filter(verifiedActivity),plans=access==='institution'?approvedReportItems(filters):[],completedPlan=plans.filter(r=>r.activity&&verifiedActivity(r.activity)),today=localDay(),overduePs=ps.filter(p=>activityControlActive(p)&&p.due<today&&!verifiedActivity(p)),evaluation=evaluationMetrics(ps),financial=['a1','sa1','f1','fv1'].includes(uid)?financeReportRows(filters):[];const approvedBudgets=financial.filter(r=>Number.isSafeInteger(r.budget.approved)),approvedCents=approvedBudgets.reduce((n,r)=>n+r.budget.approved,0),actualCents=approvedBudgets.reduce((n,r)=>n+budgetActual(r.budget),0);return {access,ps,verified,outcomes:ps.flatMap(p=>p.members.filter(id=>participantResolution(p,id)).map(student=>({activity:p,student,outcome:participantOutcomeLabel(p,student)}))),plans,completedPlan,planRate:plans.length?completedPlan.length/plans.length*100:null,participants:new Set(verified.flatMap(p=>p.members.filter(id=>successfulParticipant(p,id)))).size,overduePs,evaluation,financial,approvedCents,actualCents,varianceCents:actualCents-approvedCents,unsettled:approvedBudgets.filter(r=>r.budget.state!=='CLEARED').length,generated:new Date().toISOString()}}
function overviewDrill(kind){if(kind==='verified'&&reportAccess()==='institution'){reportDetail='verified';go('Reports');return}query='';filter='All';page='Projects';selected=null;render();if(kind==='verified'){$('#projectlist').innerHTML=projectCards(visible().filter(verifiedActivity));toast('Showing verified projects. Use filters to change the view.')}}
function reportFilterForm(){let ps=uniqueBy(db.projects,p=>p.id),programmes=[...new Set([...ps.map(p=>p.programme),...(db.plans||[]).map(p=>p.programme),'Cross-programme club activity'])].sort(),years=[...new Set([...ps.map(activityYear),...(db.plans||[]).map(p=>p.year),...db.clubs.flatMap(c=>c.plans.map(p=>p.year))])].sort();return `<form class="reportfilters" onsubmit="applyReportFilters(event)"><label>Activity deadline from<input name="from" type="date" value="${esc(reportFilters.from)}"></label><label>Activity deadline through<input name="to" type="date" value="${esc(reportFilters.to)}"></label><label>Programme<select name="programme">${['All',...programmes].map(v=>`<option ${v===reportFilters.programme?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Academic year<select name="year">${['All',...years].map(v=>`<option ${v===reportFilters.year?'selected':''}>${esc(v)}</option>`).join('')}</select></label><button class="primary">Apply filters</button><button type="button" onclick="reportFilters={from:'',to:'',programme:'All',year:'All'};reportDetail=['department','responsibilities','faculty-responsibilities','research'].includes(reportDetail)?reportDetail:'all';render()">Reset</button></form>`}
function applyReportFilters(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(f.from&&f.to&&f.from>f.to)return toast('Start date must not follow the end date.');reportFilters=f;reportDetail=['department','responsibilities','faculty-responsibilities','research'].includes(reportDetail)?reportDetail:'all';render()}
function metricCard(title,value,subtitle,drill){return `<div class="card stat"><span>${title}</span><strong>${value}</strong><small>${subtitle}</small>${drill?`<div class="buttons">${btn('View records →',`reportDetail='${drill}';render()`)}</div>`:''}</div>`}
function reportsPage(){const s=reportSnapshot();if(!s)return heading('Operational reports','Reports are limited to designated demonstration roles.')+'<div class="panel">Select KCC Administrator, Programme Coordinator, Department Head or Student Affairs for operational reporting. Finance accounts see financial records only.</div>';if(reportDetail==='research'&&s.access==='institution')return researchReportPage(s);if(reportDetail==='faculty-responsibilities'&&s.access==='institution')return facultyMentorResponsibilityReportPage(s);if(reportDetail==='responsibilities'&&s.access==='institution')return studentResponsibilityReportPage(s);if(reportDetail==='department'&&s.access==='institution')return departmentReportPage(s);return heading(s.access==='finance'?'Finance reporting':'Institutional operational reporting','Current shared demo records · KCC demonstration scope',btn('SRS coverage →',"go('SRS Coverage')"))+reportFilterForm()+(s.access==='institution'?btn('Student responsibility report','openStudentResponsibilities()')+btn('Faculty mentor responsibilities','openFacultyMentorResponsibilities()')+btn('Research activity summary','openResearchReport()'):'')+`<div class="notice"><strong>Reporting basis:</strong> activity completion deadline, inclusive date range ${esc(reportFilters.from||'earliest')} to ${esc(reportFilters.to||'latest')}; programme ${esc(reportFilters.programme)}; year ${esc(reportFilters.year)}. Generated ${esc(eventTime(s.generated))} · Nepal date ${localDay()}. Data is from the shared owner-private demo database and has no MIS synchronization. Institutional activity totals count each activity ID once. Programme breakdowns use primary programme only; shared mappings are not additional counts.</div>${s.access==='institution'?`<div class="stats">${metricCard('Activities in scope',s.ps.length,'Includes labelled unverified workflow states','all')}${metricCard('Verified completion',s.verified.length,'Verified, closed or archived activities','verified')}${metricCard('Approved plan completion',s.planRate===null?'N/A':s.planRate.toFixed(1)+'%',s.completedPlan.length+' / '+s.plans.length+' approved, non-cancelled items','planned')}${metricCard('Completion overdue',s.overduePs.length,'Past deadline; not yet completion verified','overdue')}</div><div class="stats">${metricCard('Verified participants',s.participants,'Distinct successful students in completion-verified activities','participants')}${metricCard('Mean evaluation turnaround',s.evaluation.meanHours===null?'N/A':s.evaluation.meanHours.toFixed(1)+' h',s.evaluation.done.length+' finalized evaluations with valid timestamps','evaluations')}${metricCard('Awaiting evaluation',s.evaluation.waiting.length,'Submitted individual reflections without final evaluation','waiting')}${metricCard('Participation rate','N/A','Eligible cohort/enrolment roster is not connected','')}</div>${externalReportCards(s)}${departmentOverviewPanel(s)}${reportComparisonPanel(s)}${participationReportCards(s)}<div class="grid"><div class="panel"><h2>Programme overview</h2>${programmeBreakdown(s)}</div><div class="panel"><h2>SDG-aligned verified activities</h2>${sdgBreakdown(s)}<p class="meta">Counts verified activities, not confirmed beneficiaries or measured community impact.</p></div></div><div class="panel" style="margin-top:22px"><h2>Record drill-down</h2><div class="tabs">${[['all','All activities'],['verified','Verified'],['planned','Approved plan items'],['overdue','Overdue'],['evaluations','Final evaluations'],['waiting','Awaiting evaluation'],['outcomes','Other individual outcomes'],['attendance','Attendance'],['contributions','Contributions']].map(([v,t])=>btn(t,`reportDetail='${v}';render()`,reportDetail===v?'active':'')).join('')}</div>${reportDrill(s)}</div>`:''}${['a1','sa1','f1','fv1'].includes(uid)?financeReportPanel(s):'<div class="notice">Detailed financial reporting is restricted to Finance, Student Affairs and Administrator demo accounts.</div>'}<div class="notice">Portfolio completeness and participation percentages require approved component requirements and an authoritative eligible cohort. Missing evaluation timestamps are excluded from turnaround. Attendance and contribution hours are separate verified measures. Beneficiary counts and predictive analytics are not inferred.</div><div class="buttons">${btn('Export filtered report JSON','exportReportJSON()')}${btn('Export current table CSV','exportReportCSV()')}${btn('Print / Save PDF','window.print()')}</div>`}
function programmeBreakdown(s){let groups=new Map();for(let p of s.ps){let g=groups.get(p.programme)||{total:0,verified:0};g.total++;if(verifiedActivity(p))g.verified++;groups.set(p.programme,g)}return [...groups].map(([programme,g],index)=>`<div class="row"><div><strong>${esc(programme)}</strong><div class="meta">${g.verified} verified / ${g.total} total</div></div>${btn('View',`reportSelectProgramme(${index})`)}</div>`).join('')||'<p>No activities for these filters.</p>'}
function reportSelectProgramme(index){const s=reportSnapshot();if(!s||s.access!=='institution')return;const choices=[...new Set(s.ps.map(p=>p.programme))];if(choices[index]!==undefined)reportDrillProgramme(choices[index])}function reportDrillProgramme(programme){reportFilters.programme=programme;reportDetail='all';render()}
function sdgBreakdown(s){const groups=new Map();for(const p of s.verified){let code=p.sdg||'Unmapped';groups.set(code,(groups.get(code)||0)+1)}return [...groups].map(([code,total])=>`<div class="row"><span>SDG ${esc(code)}</span><strong>${total}</strong></div>`).join('')||'<p>No completion-verified activities in this period.</p>'}
function tableHTML(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>`<td>${v}</td>`).join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}">No matching records.</td></tr>`}</tbody></table></div>`}
function reportDrill(s){if(reportDetail==='outcomes')return tableHTML(['Activity','Participant','Authorized outcome'],s.outcomes.map(r=>[esc(r.activity.title),esc(name(r.student)),pill(r.outcome)]));if(['attendance','contributions'].includes(reportDetail))return participationDrill(s,reportDetail);if(reportDetail==='planned')return tableHTML(['Plan item','Source plan','Programme / year','Deadline','Result'],s.plans.map(r=>[esc(r.title),esc(r.plan),esc(r.programme)+' · '+esc(r.year),esc(r.due),r.activity?pill(r.activity.state)+' '+btn('Open',`openProject('${r.activity.id}')`):'Not converted']));if(['evaluations','waiting'].includes(reportDetail)){let rs=reportDetail==='evaluations'?s.evaluation.done:s.evaluation.waiting;return tableHTML(['Activity','Participant','Submitted','Finalized / waiting','Open'],rs.map(r=>[esc(r.activity.title),esc(name(r.student)),esc(r.submitted),r.hours===undefined?'Pending':r.hours.toFixed(1)+' h · '+esc(r.finalized),btn('Open',`openProject('${r.activity.id}')`)]))}if(reportDetail==='participants'){let ids=[...new Set(s.verified.flatMap(p=>p.members.filter(id=>successfulParticipant(p,id))))];return tableHTML(['Participant','Verified activities'],ids.map(id=>[esc(name(id)),String(s.verified.filter(p=>p.members.includes(id)&&successfulParticipant(p,id)).length)]))}let ps=reportDetail==='verified'?s.verified:reportDetail==='overdue'?s.overduePs:s.ps;return tableHTML(['ID / activity','Programme / year','Deadline','Status','Open'],ps.map(p=>[esc(p.id)+'<br>'+esc(p.title),esc(p.programme)+' · '+esc(activityYear(p)),esc(p.due),pill(p.state),btn('Open workspace',`openProject('${p.id}')`)]))}
function financeReportPanel(s){return `<div class="panel" style="margin-top:22px"><h2>Budget and settlement</h2><div class="stats">${metricCard('Approved budgets','NPR '+money(s.approvedCents/100),'Current approved values only','')}${metricCard('Actual expenditure','NPR '+money(s.actualCents/100),'Recorded expenses against approved budgets','')}${metricCard('Budget variance','NPR '+money(s.varianceCents/100),'Actual minus approved; negative means underspend','')}${metricCard('Awaiting clearance',s.unsettled,'Approved budgets not yet CLEARED','')}</div>${tableHTML(['Activity','Budget / status','Approved NPR','Actual NPR','Variance NPR'],s.financial.map(r=>[esc(r.activity.title),esc(r.budget.id)+' · approval v'+(r.budget.approvalVersion||1)+'<br>'+pill(r.budget.state),Number.isSafeInteger(r.budget.approved)?money(r.budget.approved/100):'Not approved',money(budgetActual(r.budget)/100),Number.isSafeInteger(r.budget.approved)?money((budgetActual(r.budget)-r.budget.approved)/100):'N/A']))}${cashReportPanel(s)}<p class="meta">Balances count verified records; unreconciled legacy amounts are unknown. This is not a bank or general-ledger report.</p>${btn('Open club finance',"go('Club Finance')")}</div>`}
function reportExportData(){const s=reportSnapshot();if(!s)return null;let data={demo:true,source:'Shared-demo KCC360 dataset',periodBasis:'Activity completion deadline',filters:{...reportFilters},generated:s.generated,scope:s.access,metrics:{approvedBudgetCents:s.approvedCents,actualCents:s.actualCents,varianceCents:s.varianceCents,unsettled:s.unsettled,financialAccess:['a1','sa1','f1','fv1'].includes(uid)},financial:s.financial.map(r=>({activityId:r.activity.id,title:r.activity.title,budgetId:r.budget.id,state:r.budget.state,approvalVersion:r.budget.approvalVersion||1,originalApprovedCents:r.budget.approvalHistory?.[0]?.approved??r.budget.approved??null,approvedCents:r.budget.approved??null,actualCents:budgetActual(r.budget),cash:cashSummary(r.budget)}))};if(!['a1','sa1','f1','fv1'].includes(uid)){data.metrics.approvedBudgetCents=null;data.metrics.actualCents=null;data.metrics.varianceCents=null;data.metrics.unsettled=null}if(s.access==='institution')Object.assign(data,{departmentReporting:departmentReportExportData(),externalParticipation:externalReportSummary(s.ps),metrics:{...data.metrics,activities:s.ps.length,verified:s.verified.length,approvedPlanItems:s.plans.length,verifiedPlanItems:s.completedPlan.length,planCompletionPercent:s.planRate,distinctVerifiedParticipants:s.participants,authorizedOutcomeCounts:Object.fromEntries(['WITHDRAWN','PARTIALLY_COMPLETED','EXEMPTED'].map(outcome=>[outcome,s.outcomes.filter(r=>r.outcome===outcome).length])),overdue:s.overduePs.length,meanEvaluationHours:s.evaluation.meanHours,awaitingEvaluation:s.evaluation.waiting.length,participationRate:null,portfolioCompleteness:null,verifiedAttendanceMinutes:participationMetrics(s.ps).attendanceMinutes,verifiedContributionMinutes:participationMetrics(s.ps).contributionMinutes},individualOutcomes:s.outcomes.map(r=>({activityId:r.activity.id,student:r.student,outcome:r.outcome})),programmeSummaries:reportGroupData(s.ps),clubSummaries:reportGroupData(s.ps,true),activities:s.ps.map(p=>({id:p.id,title:p.title,programme:p.programme,year:activityYear(p),deadline:p.due,state:p.state})),planItems:s.plans.map(r=>({id:r.id,title:r.title,plan:r.plan,deadline:r.due,activityId:r.activity?.id||null,verified:!!r.activity&&verifiedActivity(r.activity)}))});return data}
function exportReportJSON(){const data=reportDetail==='department'?departmentReportExportData():reportExportData();if(!data)return toast('Reporting access required.');download(data,reportDetail==='department'?'KCC360-department-report.json':'KCC360-filtered-operational-report.json')}
function csvSafe(v){let text=String(v??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}
function reportCSVRows(){const s=reportSnapshot();if(!s)return null;if(s.access==='finance')return [['Activity ID','Activity','Budget ID','Status','Approved NPR','Actual NPR','Cash reconciled','Net paid NPR','Refund due NPR','Reimbursement payable NPR'],...s.financial.map(r=>{let cash=cashSummary(r.budget);return [r.activity.id,r.activity.title,r.budget.id,r.budget.state,r.budget.approved===undefined?'':r.budget.approved/100,budgetActual(r.budget)/100,cash.known,cash.known?cash.netPaid/100:'Unknown',cash.known?cash.refundDue/100:'Unknown',cash.known?cash.payable/100:'Unknown']})];if(reportDetail==='department')return departmentReportCSVRows();if(reportDetail==='outcomes')return [['Activity ID','Participant','Authorized outcome'],...s.outcomes.map(r=>[r.activity.id,name(r.student),r.outcome])];if(['attendance','contributions'].includes(reportDetail)){const rows=participationMetrics(s.ps)[reportDetail];return [['Activity ID','Participant','Record ID','Date','Minutes','Source'],...rows.map(r=>[r.activity.id,name(r.student),r.id,r.date,r.minutes,r.source])]}if(reportDetail==='planned')return [['Item ID','Title','Plan','Deadline','Activity ID','Status'],...s.plans.map(r=>[r.id,r.title,r.plan,r.due,r.activity?.id||'',r.activity?.state||'Not converted'])];if(['evaluations','waiting'].includes(reportDetail)){let rs=reportDetail==='evaluations'?s.evaluation.done:s.evaluation.waiting;return [['Activity ID','Participant','Submitted','Finalized','Hours'],...rs.map(r=>[r.activity.id,name(r.student),r.submitted,r.finalized||'',r.hours??''])]}if(reportDetail==='participants'){let ids=[...new Set(s.verified.flatMap(p=>p.members.filter(id=>successfulParticipant(p,id))))];return [['Participant','Verified activity count'],...ids.map(id=>[name(id),s.verified.filter(p=>p.members.includes(id)&&successfulParticipant(p,id)).length])]}let ps=reportDetail==='verified'?s.verified:reportDetail==='overdue'?s.overduePs:s.ps;return [['ID','Title','Programme','Year','Deadline','Status'],...ps.map(p=>[p.id,p.title,p.programme,activityYear(p),p.due,p.state])]}
function exportReportCSV(){let rows=reportCSVRows();if(!rows)return toast('Reporting access required.');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(csvSafe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download='KCC360-filtered-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
