const srsDecisions=[['Club evaluation and renewal','Student Affairs / Academic authority','Mandatory structured-evaluation adoption, any club scoring weights, conditional renewal and corrective-action closure verification.'],['Task/domain performance','Academic authority','Approve task scale, domain aggregation and coverage interpretation; demo averages do not determine grades.'],['Academic placement authority','Academic Administration / MIS owner','Approve complete programme period/year mappings, roster/source identifiers, authority mode and held-student eligibility.'],['Rubrics and recognition','Academic authority','Weights, scales, rounding, pass and certificate thresholds; demo values remain provisional.'],['Withdrawal and exemptions','Academic / Student Affairs','Partial completion, withdrawal and individual eligibility.'],['Permissions','Institutional sponsor / process owners','Role grants, delegation, scopes and separation-of-duty exceptions.'],['LMS adapter','Academic authority / integration team','Target LMS, protocol, grade direction and mapping.'],['MIS interface','MIS owner / integration team','E-Digital Nepal authentication contract and sync interval.'],['Performance sizing','Sponsor / technical lead','Concurrent workload, volumes, file sizes and infrastructure.'],['Recovery and retention','Sponsor / operations / records authority','RPO/RTO, backup schedule, retention categories and restore rehearsal.'],['Privacy and alumni access','Designated institutional authorities','Consent, public sharing, continuing access and record retention.'],['Operational settings','Process owners / technical lead','File rules, timeouts, notification and escalation intervals.'],['Architecture baseline','Technical lead / sponsor','Backend, frontend, hosting, browser matrix and identity controls.'],['Optional AI extension','Academic / privacy authorities','Provider, data handling and multilingual validation.']];
function coveragePage(){let gaps=srsReconciliation.gaps.filter(g=>(reconciliationPriority==='All'||g.priority===reconciliationPriority)&&(reconciliationCategory==='All'||g.category===reconciliationCategory));return heading('SRS reconciliation & remaining work','Reviewed '+srsReconciliation.reviewDate+' · Prototype through Stage '+(srsReconciliation.repairStage||srsReconciliation.baselineStage),btn('Export reconciliation JSON','exportCoverage()'))+`<div class="notice"><strong>This register is not a production acceptance certificate.</strong> It reconciles the consolidated draft with inspected source and targeted fixtures. The register separates regression-checked implementations from 21 remaining integration, policy and acceptance entries. No readiness percentage or complete AT pass is inferred. The source SRS and institutional policies remain unchanged.</div><div class="stats">${metricCard('Implemented register entries',srsReconciliation.gaps.filter(g=>g.status!=='Open').length,'Synthetic in-memory probes, not live data','')}${metricCard('Open register entries',srsReconciliation.gaps.filter(g=>g.status==='Open').length,'Mixed defects, integrations and policy work','')}${metricCard('Acceptance cases mapped',srsReconciliation.acceptance.length,'AT-01 through AT-15; none certified passed','')}${metricCard('Production gates',srsReconciliation.gaps.filter(g=>g.priority==='P0').length,'Must close before real institutional use','')}</div>${dashboardCoveragePanel()}${permissionFoundationPanel()}<section class="panel"><h2>Unrated monitoring sandbox</h2><p>Explore plan review, evidence of effectiveness and corrective-action follow-up using a fictional scenario. Entries stay in the new tab’s memory. Live plans, faculty ratings and permissions are unchanged.</p><a class="button" href="monitoring-sandbox.html" target="_blank" rel="noopener">Open isolated monitoring sandbox ↗</a></section><section class="panel"><h2>Club corrective-action closure sandbox</h2><p>Try one fictional owner/reviewer cycle. Tab memory only; no live saving, sign-in, action closure or club renewal.</p><a class="button" href="club-closure-sandbox.html" target="_blank" rel="noopener noreferrer">Open isolated club closure sandbox ↗</a></section>${departmentDashboardPlanPanel()}${reflectionPublicationPlanPanel()}<div class="panel"><h2>Next repair and acceptance sequence</h2><ol>${srsReconciliation.nextSteps.map(s=>`<li><strong>${esc(s.step)}</strong><p>${esc(s.deliverable)}</p></li>`).join('')}</ol></div><div class="panel" style="margin-top:22px"><h2>Prioritized gap register</h2><p>P1 = next functional work; P0 = mandatory production gate; P2 = controlled/optional release. These are planning priorities, not institutional approvals.</p><div class="performance-filters"><label>Priority<select onchange="reconciliationPriority=this.value;render()">${['All','P0','P1','P2'].map(v=>`<option ${reconciliationPriority===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Category<select onchange="reconciliationCategory=this.value;render()">${['All',...new Set(srsReconciliation.gaps.map(g=>g.category))].map(v=>`<option ${reconciliationCategory===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label></div>${tableHTML(['Gap / priority / requirement','Observed behavior','Closure criterion','Owner / evidence'],gaps.map(g=>[esc(g.id)+' · '+esc(g.priority)+' · '+esc(g.status)+'<br><strong>'+esc(g.title)+'</strong><p>'+esc(g.refs)+'</p>',esc(g.observed),esc(g.closure),esc(g.owner)+'<p>'+g.evidence.map(esc).join('<br>')+'</p>']))}</div><section class="panel"><h2>Isolated multi-role walkthrough</h2><p>One fictional person with several scoped grants. View switching, revocation, expiry, explicit denial and self-verification checks use existing pilot adapters. In-memory demonstration only; live accounts and permissions are unchanged.</p><a class="buttonlink" href="multi-role-sandbox.html" target="_blank" rel="noopener noreferrer">Open multi-role walkthrough</a></section>${finalizationReadinessPanel()}${workflowAcceptancePanel()}${acceptanceReadinessPanel()}${prototypeAcceptanceWalkthroughPanel()}<div class="panel" style="margin-top:22px"><h2>Module implementation evidence</h2><p>Logic checked means targeted fictional-data checks, not complete SRS acceptance. Remaining work has been reconciled to avoid listing already-delivered graphs, placement imports or portfolio sharing as absent.</p>${tableHTML(['SRS reference / module','Prototype status','Current evidence','Remaining work','Open module'],srsCoverage.map(r=>[esc(r.ref)+'<br><strong>'+esc(r.module)+'</strong>',esc(r.state),esc(r.demo),esc(r.remaining),r.route?btn('Open',`go('${r.route}')`):'—']))}</div><div class="panel" style="margin-top:22px"><h2>Annex F · Institutional decisions</h2><p>These decisions remain unapproved in this prototype; demonstration configuration is not policy adoption.</p>${tableHTML(['Decision area','Responsible authority','Required resolution'],srsDecisions.map(r=>r.map(esc)))}</div><details><summary>Review provenance and limits</summary><p>${esc(srsReconciliation.sourceTitle)} · ${esc(srsReconciliation.sourceDate)} · ${esc(srsReconciliation.sourceStatus)}</p><p>${esc(srsReconciliation.sourcePages)}</p><p>Source baseline: ${esc(srsReconciliation.baselineCommit)}</p><ul>${srsReconciliation.limitations.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul></details>`}

function exportCoverage(){download({source:'KCC360 Master SRS v3.0 consolidated draft, 13 October 2026',assessment:'Prototype coverage; not production acceptance',generated:new Date().toISOString(),reconciliation:srsReconciliation,entries:srsCoverage,configurationDecisions:srsDecisions},'KCC360-SRS-v3-prototype-coverage.json')}

function departmentOverviewRows(filters=reportFilters){
  const s=reportSnapshot(filters);if(!s||s.access!=='institution')return null;
  const groups=new Map(),group=raw=>{const label=typeof raw==='string'&&raw.trim()?raw.trim():null,key=label===null?'unmapped':JSON.stringify(['label',label]);if(!groups.has(key))groups.set(key,{label:label||'Department not recorded',unmapped:label===null,activities:[],planItems:[]});return groups.get(key)};
  for(const p of s.ps)group(p.planningMetadata?.department).activities.push(p);
  for(const row of s.plans)group(row.department).planItems.push(row);
  return [...groups.values()].sort((a,b)=>Number(a.unmapped)-Number(b.unmapped)||a.label.localeCompare(b.label)).map(g=>{const completed=g.planItems.filter(r=>r.activity&&verifiedActivity(r.activity)).length;return {...g,...reportTaskSummary(g.activities),total:g.activities.length,verified:g.activities.filter(verifiedActivity).length,cancelled:g.activities.filter(p=>p.activityControl?.state==='CANCELLED').length,overdue:g.activities.filter(p=>activityControlActive(p)&&p.due<localDay()&&!verifiedActivity(p)).length,approvedPlanItems:g.planItems.length,completedPlanItems:completed,planRate:g.planItems.length?100*completed/g.planItems.length:null}});
}
function departmentOverviewPanel(s){
  if(!s||s.access!=='institution')return '';const rows=departmentOverviewRows();if(!rows)return '';
  return `<section class="panel" style="margin-top:22px"><h2>Provisional department overview</h2><p>Grouped by the department label retained from the source academic plan. These free-text labels are not authoritative MIS departments or access permissions. Current report filters and existing activity visibility apply; no department is inferred from programme or student placement.</p>${tableHTML(['Source department label','Activities','Verified completion','Cancelled','Overdue (not formally incomplete)','Approved plan items / verified','Plan completion','Source records'],rows.map(g=>[esc(g.label)+(g.unmapped?' <span class="pill">Unmapped</span>':''),g.total,g.verified,g.cancelled,g.overdue,g.approvedPlanItems+' / '+g.completedPlanItems,g.planRate===null?'N/A':g.planRate.toFixed(1)+'%','<details><summary>View '+g.total+' records</summary>'+tableHTML(['Activity','Type as recorded','Workflow state'],g.activities.map(p=>[esc(p.title),esc(p.type||'Not recorded'),esc(p.state)]))+'</details>'+departmentPlanSourceTable(g)]))}<p class="meta">${s.ps.length} distinct activities; ${rows.filter(g=>g.unmapped).reduce((n,g)=>n+g.total,0)} without department metadata. Empty results mean no visible records for these filters. Verified completion reuses existing verification rules. Cancelled records remain visible as history; overdue is a separate indicator. Counts use each activity ID once and one retained label; shared departmental mappings, engagement classifications and counseling lists remain pending. Period basis: activity deadline. Generated ${esc(eventTime(s.generated))}. Activity labels reflect the source plan at conversion; plan-item labels come from the latest approved plan revision. These may differ and are not current student enrolment. Plan completion = verified linked approved items / approved non-cancelled items × 100; zero denominator = N/A. Plan items use their own end date for the reporting period; linked activities use their own deadline in the activity counts. Club items without department metadata remain unmapped. An item and its execution record are not added together as activities.</p>${departmentDomainCharts(rows)}${departmentTaskPerformanceTable(rows)}${departmentTaskSources(rows)}</section>`;
}

function departmentPlanSourceTable(g){return g.planItems.length?'<details><summary>View '+g.planItems.length+' approved plan items</summary>'+tableHTML(['Plan / item','Kind','Item deadline','Linked activity','Verified completion'],g.planItems.map(r=>[esc(r.plan)+' / '+esc(r.id)+'<br>'+esc(r.title),esc(r.kind),esc(r.due),esc(r.activity?.title||'Not converted'),r.activity&&verifiedActivity(r.activity)?'Yes':'No']))+'</details>':'<p class="meta">No approved plan items for this label and period.</p>'}

function openDepartmentReport(){if(reportAccess()!=='institution')return toast('Department reporting is unavailable to this account.');reportDetail='department';go('Reports')}
function openOperationalReports(){if(!reportAccess())return toast('Reporting is unavailable to this account.');reportDetail='all';go('Reports')}
function departmentReportingDashboardCard(){
  if(reportAccess()!=='institution')return '';const rows=departmentOverviewRows(),mapped=rows.filter(g=>!g.unmapped).length,unmapped=rows.filter(g=>g.unmapped).reduce((n,g)=>n+g.total,0);
  return `<section class="panel"><h2>Department reporting</h2><p>${mapped} source department labels · ${unmapped} activities without department metadata. Provisional labels summarize existing records; they do not establish departmental access.</p><p class="meta">Current reporting filters: deadline ${esc(reportFilters.from||'earliest')} to ${esc(reportFilters.to||'latest')} · Programme ${esc(reportFilters.programme)} · Academic year ${esc(reportFilters.year)}. Shared demo scope; no MIS synchronization. This is a reporting summary, not an assigned approval queue.</p>${btn('Open department reporting overview','openDepartmentReport()')}</section>`;
}
function departmentReportPage(s){return heading('Department reporting overview','Reports module · Provisional academic-plan source labels',btn('All operational reports','openOperationalReports()'))+reportFilterForm()+`<p class="notice">Current programme, year and inclusive deadline filters apply. Generated ${esc(eventTime(s.generated))}. Existing demonstration reporting permissions apply; these labels are not institutional department assignments. Expand a source-record list below for the detailed process records. Engagement classifications and restricted counseling cases remain pending.</p>`+departmentOverviewPanel(s)+`<div class="buttons">${btn('Export department JSON','exportReportJSON()')}${btn('Export department CSV','exportReportCSV()')}${btn('Print / Save PDF','window.print()')}</div>`}

function departmentTaskPerformanceTable(rows){return `<h3>Assigned-task completion and four-domain performance</h3>${tableHTML(['Source department label','Mapped tasks / verified','Task completion',...Object.values(taskDomainNames).map(d=>d+' · mean / 4; coverage')],rows.map(g=>[esc(g.label),g.assignedTasks+' / '+g.verifiedTasks,g.taskCompletionPercent===null?'N/A':g.taskCompletionPercent.toFixed(1)+'%',...g.domains.map(d=>(d.mean===null?'N/A':d.mean.toFixed(2))+' · '+d.assessed+'/'+d.assigned+' assessed'+(d.coverage===null?' · N/A coverage':' · '+(100*d.coverage).toFixed(1)+'% coverage')+' · '+d.verified+' verified')]))}<p class="meta">Mapped tasks are assigned responsibilities on visible, non-cancelled activities in the current activity-deadline/programme/year filters. Legacy unmapped tasks are excluded. Completion uses current mentor verification; reopened tasks and changed supporting evidence cease to count as verified. Per domain, coverage = assessed / assigned mapped tasks; a task may contribute to several domains. Scores use the existing demo 0–4 scale and equal task weights. A recorded zero remains zero; missing scores and no assigned opportunities display N/A. Means describe assessed verified work only and require coverage to interpret them. These are not grades, student engagement categories, departmental rankings or counseling diagnoses. Plan-only rows have no assigned-task denominator. No individual reflection, submission or review comments are displayed.</p>`}

function departmentReportExportData(){
  const rows=departmentOverviewRows();if(!rows)return null;
  return {demo:true,report:'Provisional department summary',source:'Shared-demo KCC360 dataset; no MIS synchronization',scope:'Existing institution-reporting demo permission',generated:new Date().toISOString(),filters:{...reportFilters},activityPeriodBasis:'Activity deadline, inclusive dates',planPeriodBasis:'Approved item end date, inclusive dates',departmentBasis:'Activity: retained conversion label; plan item: latest approved source plan label; missing labels remain unmapped',verificationBasis:'Existing completion verification; current mapped-task mentor verification and evidence binding; cancelled responsibilities excluded',planFormula:'Verified linked approved non-cancelled items / approved non-cancelled items × 100; zero denominator = null',taskFormula:'Current verified mapped tasks / assigned mapped tasks × 100; zero denominator = null',domainBasis:'DEMO_0_4_V1; equal task weights; coverage = assessed / assigned domain tasks (fraction 0–1); zero is a score, missing mean/coverage is null',limitations:['Provisional source labels are not authoritative departments or permissions.','Activity and plan item period/labels may differ; do not add item counts to activities.','No grades, institutional rankings, engagement classification or counseling diagnosis.','No individual submissions, reflections, assessment comments, contacts or financial data included.','CSV repeats aggregate totals on each of four domain rows; do not sum these totals across domains.'],summaries:rows.map(g=>({label:g.label,unmapped:g.unmapped,activities:g.total,verifiedActivities:g.verified,cancelledActivities:g.cancelled,overdueActivities:g.overdue,approvedPlanItems:g.approvedPlanItems,completedPlanItems:g.completedPlanItems,planCompletionPercent:g.planRate,assignedTasks:g.assignedTasks,verifiedTasks:g.verifiedTasks,taskCompletionPercent:g.taskCompletionPercent,domains:g.domains.map(d=>({...d}))}))};
}
function departmentReportCSVRows(){
  const data=departmentReportExportData();if(!data)return null;
  const head=['Row kind','Demo','Generated','Scope','Deadline from','Deadline through','Programme','Academic year','Activity period basis','Plan period basis','Department basis','Verification basis','Domain scale and coverage basis','Limitations','Department label','Unmapped','Activities','Verified activities','Cancelled activities','Overdue activities','Approved plan items','Completed plan items','Plan completion percent','Assigned tasks','Verified tasks','Task completion percent','Domain','Domain assigned','Domain verified','Domain assessed','Domain mean / 4','Domain coverage fraction'];
  const prefix=[true,data.generated,data.scope,data.filters.from||'earliest',data.filters.to||'latest',data.filters.programme,data.filters.year,data.activityPeriodBasis,data.planPeriodBasis,data.departmentBasis,data.verificationBasis,data.domainBasis,data.limitations.join(' ')],value=v=>v===null?'N/A':v;
  const rows=data.summaries.flatMap(g=>g.domains.map(d=>['SUMMARY',...prefix,g.label,g.unmapped,g.activities,g.verifiedActivities,g.cancelledActivities,g.overdueActivities,g.approvedPlanItems,g.completedPlanItems,value(g.planCompletionPercent),g.assignedTasks,g.verifiedTasks,value(g.taskCompletionPercent),taskDomainNames[d.domain],d.assigned,d.verified,d.assessed,value(d.mean),value(d.coverage)]));
  if(!rows.length)rows.push(['NO_MATCHING_RECORDS',...prefix,...Array(head.length-prefix.length-1).fill('N/A')]);
  return [head,...rows];
}

function departmentDomainCharts(rows){
  if(reportAccess()!=='institution')return '';
  return `<h3>Four-domain visual summary</h3><p class="meta">Verified assessed-task means on the existing demo scale, 0–4. Coverage is shown separately from score. Exact counts and values follow in the table; these charts are descriptive, not rankings.</p><div class="department-domain-grid">${rows.map(g=>`<article class="card"><h4>${esc(g.label)}${g.unmapped?' · Unmapped source':''}</h4>${departmentDomainChart(g)}<p class="meta">${g.verifiedTasks} / ${g.assignedTasks} mapped tasks currently verified · ${g.taskCompletionPercent===null?'N/A':g.taskCompletionPercent.toFixed(1)+'%'} completion. Activity deadline and current report filters apply.</p></article>`).join('')||'<p>No visible activity or approved-plan records match these filters.</p>'}</div>`;
}
function departmentDomainChart(g){
  if(reportAccess()!=='institution')return '';
  const x=190,width=220,y=i=>55+i*70,available=g.domains.filter(d=>d.mean!==null).length;
  return `<svg class="department-domain-chart" viewBox="0 0 600 350" role="img" aria-label="${esc(g.label)}: four-domain means from zero to four; ${available} domains assessed. Missing scores have no marker. Exact values and coverage appear below."><title>${esc(g.label)} · assessed-task performance and coverage</title><desc>Each domain shows its mean on the demo zero-to-four scale and assessed versus assigned coverage. A recorded zero has a marker at the origin; missing scores have no marker. These are not student grades or engagement categories.</desc>${[0,1,2,3,4].map(n=>`<line x1="${x+n*width/4}" y1="34" x2="${x+n*width/4}" y2="280" stroke="#e1e7ed"/><text x="${x+n*width/4}" y="22" text-anchor="middle" fill="#526c78" font-size="13">${n}</text>`).join('')}${g.domains.map((d,i)=>`<text x="12" y="${y(i)+5}" font-size="14" fill="#28475b">${esc(taskDomainNames[d.domain])}</text>${d.mean===null?'':`<rect data-domain="${esc(d.domain)}" x="${x}" y="${y(i)-9}" width="${d.mean*width/4}" height="18" rx="3" fill="#137c69"/><circle data-score="${d.mean}" cx="${x+d.mean*width/4}" cy="${y(i)}" r="4" fill="#137c69"/>`}<text x="430" y="${y(i)+5}" font-size="14" fill="#28475b">${d.mean===null?'N/A · not assessed':d.mean.toFixed(2)+' / 4'}</text><text x="190" y="${y(i)+26}" font-size="12" fill="#526c78">${d.assessed} / ${d.assigned} assessed · ${d.coverage===null?'N/A':(100*d.coverage).toFixed(1)+'%'} coverage</text>`).join('')}<text x="12" y="327" font-size="12" fill="#526c78">${available} / 4 domains assessed · missing scores are not plotted as zero</text></svg>`;
}

function departmentTaskSources(groups){
  if(reportAccess()!=='institution')return '';
  return `<h3>Task source records</h3><p class="meta">Mapped responsibilities from the same activity scope as the summaries. Current verification and valid assessed scores determine inclusion; a workflow label alone does not establish verification. Open the activity Tasks view for its existing authorized process. Private submissions and review comments are not included here.</p>${groups.map(g=>{const rows=reportTaskRows(g.activities).filter(r=>r.t.mappingVersion);return `<details><summary>${esc(g.label)} · ${rows.length} mapped task records</summary>${tableHTML(['Activity / task','Assigned student','Workflow state','Current verified completion',...Object.values(taskDomainNames).map(d=>d+' / 4'),'Source process'],rows.map(r=>[esc(r.p.title)+'<br>'+esc(r.t.title)+'<p class="meta">'+esc(r.p.id)+' / '+esc(r.t.id)+'</p>',esc(name(r.t.assignee)),esc(r.t.workState||'ASSIGNED'),r.verified?'Yes':'No',...Object.keys(taskDomainNames).map(d=>!r.t.domains.includes(d)?'Not assigned':performanceScore(r,d)===null?'N/A':String(performanceScore(r,d))),btn('Open activity tasks',esc('openDepartmentTask('+JSON.stringify(r.p.id)+','+JSON.stringify(r.t.id)+')'))]))}${rows.length?'':'<p>No mapped tasks in this source group.</p>'}</details>`}).join('')||'<p>No task source groups match the current filters.</p>'}`;
}
function openDepartmentTask(projectId,taskId){
  if(reportAccess()!=='institution')return toast('Department task reporting is unavailable to this account.');
  const groups=departmentOverviewRows(),row=groups.flatMap(g=>reportTaskRows(g.activities)).find(r=>r.p.id===projectId&&r.t.id===taskId&&r.t.mappingVersion);
  if(!row||!canSee(row.p))return toast('This task source is no longer available in the current report scope.');
  selected=row.p.id;page='Projects';tab='Tasks';render();
}

// Read-only assignment reporting; never a complete cohort or engagement classification.
let studentResponsibilityQuery='';
function studentResponsibilityRows(search=studentResponsibilityQuery){
 if(reportAccess()!=='institution')return null;
 const term=String(search).trim().toLocaleLowerCase();const rows=[];
 for(const p of uniqueBy(visible().filter(p=>reportMatch(p,reportFilters)),p=>p.id)){
  for(const student of [...new Set(p.members)].filter(id=>['s1','s2'].includes(id))){
   if(term&&!`${student} ${name(student)}`.toLocaleLowerCase().includes(term))continue;
   const mapped=(p.tasks||[]).filter(t=>t.assignee===student&&t.mappingVersion),legacy=(p.tasks||[]).filter(t=>t.assignee===student&&!t.mappingVersion);
   const outcome=participantResolution(p,student),current=activityControlActive(p)&&!outcome;
   rows.push({student,studentName:name(student),activityId:p.id,title:p.title,type:p.type||'Not recorded',programme:p.programme||'Not recorded',semester:p.planningMetadata?.semester||null,mentor:p.mentor?name(p.mentor):'Not assigned',state:p.state,control:p.activityControl?.state||'ACTIVE',outcome:outcome?participantOutcomeLabel(p,student):null,current,mappedTasks:mapped.length,verifiedTasks:current?mapped.filter(t=>taskAssessmentCurrent(p,t)).length:null,legacyTasks:legacy.length,deadline:p.due,tasks:mapped.map(t=>({title:t.title,due:t.due||null,state:current?taskBoardStage(p,t):'HISTORICAL_OR_PAUSED'}))});
  }
 }
 return rows.sort((a,b)=>a.studentName.localeCompare(b.studentName)||a.title.localeCompare(b.title));
}
function openStudentResponsibilities(){if(reportAccess()!=='institution')return toast('Student responsibility reporting is unavailable to this account.');reportDetail='responsibilities';go('Reports')}
function searchStudentResponsibilities(event){event.preventDefault();if(reportAccess()!=='institution')return toast('Reporting access required.');const value=new FormData(event.target).get('student');if(typeof value!=='string'||value.length>100)return toast('Use a student name or ID of at most 100 characters.');studentResponsibilityQuery=value.trim();reportDetail='responsibilities';render()}
function openStudentResponsibilitySource(activityId,student){const rows=studentResponsibilityRows();if(!rows?.some(r=>r.activityId===activityId&&r.student===student))return toast('This responsibility is no longer available within the current report scope.');const p=db.projects.find(p=>p.id===activityId);if(!p||!canSee(p))return toast('Activity access unavailable.');openProject(activityId)}
function studentResponsibilityReportPage(s){
 const rows=studentResponsibilityRows();if(!rows)return '';
 return heading('Student responsibility report','Reports overview → Recorded student assignments → Permitted activity detail',btn('All operational reports','openOperationalReports()'))+reportFilterForm()+`<form class="filters" onsubmit="searchStudentResponsibilities(event)"><label>Student name or demo ID<input name="student" maxlength="100" value="${esc(studentResponsibilityQuery)}" placeholder="Search students in visible activity records"></label><button class="primary">Search</button><button type="button" onclick="studentResponsibilityQuery='';render()">Clear student search</button></form><div class="notice">Available-record report, not a complete class roster. Students without a visible activity are not listed; absence does not mean inactive or zero participation. Programme, semester and year are activity-source labels, not authoritative current enrolment. Existing programme/year and activity-deadline filters apply. Generated ${esc(eventTime(s.generated))}. Student-declared CV content, private feedback, grades and counseling records are excluded.</div><section class="panel"><h2>Recorded responsibilities</h2><p>${new Set(rows.map(r=>r.student)).size} students represented · ${rows.length} distinct student/activity records. These are not full-cohort totals.</p>${tableHTML(['Student','Activity / type','Activity programme / source semester','Assigned mentor','Workflow / control / individual outcome','Mapped tasks / currently verified','Deadline','Recorded task assignments','Detail'],rows.map(r=>[esc(r.studentName)+' · '+esc(r.student),esc(r.title)+'<br>'+esc(r.type),esc(r.programme)+'<br>'+(r.semester?'Source semester: '+esc(r.semester):'Semester not recorded'),esc(r.mentor),esc(r.state)+' · '+esc(r.control)+(r.outcome?' · '+esc(r.outcome):''),r.mappedTasks+' / '+(r.verifiedTasks===null?'N/A (paused or resolved)':r.verifiedTasks)+'<br>'+r.legacyTasks+' legacy tasks excluded',esc(r.deadline),'<details><summary>View '+r.tasks.length+' mapped assignments</summary>'+r.tasks.map(t=>'<p>'+esc(t.title)+' · '+esc(t.due||'No task deadline')+' · '+esc(t.state)+'</p>').join('')+'</details>',btn('Open activity',esc('openStudentResponsibilitySource('+JSON.stringify(r.activityId)+','+JSON.stringify(r.student)+')'))]))}${rows.length?'':'<p>No matching visible student/activity records. Full-class coverage is unavailable.</p>'}<p class="meta">Mapped task totals are recorded assignments. Current verified counts use existing mentor verification and source-freshness rules. Paused/cancelled or individually resolved participation is retained as history with current verification N/A. Legacy self-reported tasks are shown separately. Task counts do not rate students or faculty. Junior mentoring and other faculty responsibilities require explicit assignment sources and are outside this report.</p></section>`;
}

let facultyMentorReportQuery='';
function facultyMentorResponsibilityRows(search=facultyMentorReportQuery){
 if(reportAccess()!=='institution')return null;
 const term=String(search).trim().toLocaleLowerCase();
 return uniqueBy(visible().filter(p=>reportMatch(p,reportFilters)),p=>p.id).map(p=>{
  const mentorId=p.mentor||null,mentorName=mentorId?name(mentorId):'Not assigned';
  const students=[...new Set(p.members)].filter(id=>['s1','s2'].includes(id));
  const activeStudents=students.filter(id=>!participantResolution(p,id));
  const active=activityControlActive(p),completed=verifiedActivity(p);
  const tasks=(p.tasks||[]).filter(t=>t.mappingVersion&&activeStudents.includes(t.assignee));
  return {activityId:p.id,title:p.title,type:p.type||'Not recorded',mentorId,mentorName,department:typeof p.planningMetadata?.department==='string'&&p.planningMetadata.department.trim()?p.planningMetadata.department.trim():null,programme:p.programme||'Not recorded',semester:p.planningMetadata?.semester||null,deadline:p.due,state:p.state,control:p.activityControl?.state||'ACTIVE',completed,ongoing:active&&!completed&&!['CREATED','PENDING_APPROVAL'].includes(p.state),overdue:active&&!completed&&p.due<localDay(),students:students.map(id=>({id,name:name(id),outcome:participantResolution(p,id)?participantOutcomeLabel(p,id):null})),awaitingTaskReview:active&&!completed?tasks.filter(t=>t.workState==='SUBMITTED').length:null};
 }).filter(r=>!term||`${r.mentorId||''} ${r.mentorName}`.toLocaleLowerCase().includes(term)).sort((a,b)=>a.mentorName.localeCompare(b.mentorName)||a.title.localeCompare(b.title));
}
function openFacultyMentorResponsibilities(){if(reportAccess()!=='institution')return toast('Faculty mentor responsibility reporting is unavailable to this account.');reportDetail='faculty-responsibilities';go('Reports')}
function searchFacultyMentorResponsibilities(event){event.preventDefault();if(reportAccess()!=='institution')return toast('Reporting access required.');const value=new FormData(event.target).get('mentor');if(typeof value!=='string'||value.length>100)return toast('Use a mentor name or ID of at most 100 characters.');facultyMentorReportQuery=value.trim();reportDetail='faculty-responsibilities';render()}
function openFacultyMentorResponsibilitySource(activityId,mentorId){const row=facultyMentorResponsibilityRows()?.find(r=>r.activityId===activityId&&r.mentorId===mentorId),p=db.projects.find(p=>p.id===activityId);if(!row||!p||!canSee(p))return toast('The assignment or report scope changed. Refresh the report.');openProject(activityId)}
function facultyMentorResponsibilityReportPage(s){
 const rows=facultyMentorResponsibilityRows();if(!rows)return '';
 return heading('Faculty mentor responsibility report','Reports overview → Recorded mentor assignments → Permitted activity detail',btn('All operational reports','openOperationalReports()'))+reportFilterForm()+`<form class="filters" onsubmit="searchFacultyMentorResponsibilities(event)"><label>Mentor name or demo ID<input name="mentor" maxlength="100" value="${esc(facultyMentorReportQuery)}" placeholder="Search recorded mentor assignments"></label><button class="primary">Search</button><button type="button" onclick="facultyMentorReportQuery='';render()">Clear mentor search</button></form><div class="notice">Activity mentor assignments only. This is not a full faculty-duty register, teaching timetable, workload limit or performance rating. Source department/programme/semester labels belong to activities; they do not establish the mentor's institutional department or access rights. Intake requests, club adviser duties, junior mentoring and other support assignments are not added to these counts. Generated ${esc(eventTime(s.generated))}.</div><section class="panel"><h2>Recorded activity assignments</h2><p>${new Set(rows.filter(r=>r.mentorId).map(r=>r.mentorId)).size} recorded mentors · ${rows.length} distinct activities · ${rows.filter(r=>r.completed).length} completion-verified activities. These counts do not describe every faculty member or duty.</p>${tableHTML(['Recorded mentor','Activity / type','Source department / programme / semester','Workflow / control','Recorded students','Deadline / overdue indicator','Submitted mapped tasks awaiting mentor review','Detail'],rows.map(r=>[esc(r.mentorName)+(r.mentorId?' · '+esc(r.mentorId):''),esc(r.title)+'<br>'+esc(r.type),esc(r.department||'Department not recorded')+'<br>'+esc(r.programme)+'<br>'+(r.semester?'Source semester: '+esc(r.semester):'Semester not recorded'),esc(r.state)+' · '+esc(r.control),r.students.map(student=>esc(student.name)+' · '+esc(student.id)+(student.outcome?' · '+esc(student.outcome):'')).join('<br>')||'No known student records',esc(r.deadline)+(r.overdue?'<br>Past activity deadline; not formally incomplete':''),r.awaitingTaskReview===null?'N/A (paused/cancelled/completed)':String(r.awaitingTaskReview),btn('Open activity',esc('openFacultyMentorResponsibilitySource('+JSON.stringify(r.activityId)+','+JSON.stringify(r.mentorId)+')'))]))}${rows.length?'':'<p>No matching visible activity mentor assignments. Full faculty coverage is unavailable.</p>'}<p class="meta">One row per visible activity, using its currently recorded mentor. An approved transfer changes that assignment; pending transfers do not. Completed/cancelled activities remain labelled historical source records, rather than live workload. Submitted task counts exclude resolved student participation, unmapped legacy tasks and paused/cancelled work. No private reviews, grades, CV declarations or counseling details are displayed. Open the source workflow for authorized communication and review; this report grants no new approval or sending authority.</p></section>`;
}

function researchReportSnapshot(){
 if(reportAccess()!=='institution')return null;
 const activities=uniqueBy(visible().filter(p=>p.type==='Research'&&reportMatch(p,reportFilters)),p=>p.id).map(p=>({id:p.id,title:p.title,programme:p.programme,semester:p.planningMetadata?.semester||null,mentor:p.mentor?name(p.mentor):'Not assigned',state:p.state,control:p.activityControl?.state||'ACTIVE',deadline:p.due,completed:verifiedActivity(p)}));
 const requests=uniqueBy((db.activityIntakes||[]).filter(r=>intakeVisible(r)&&!!intakeLatest(r)),r=>r.id).flatMap(r=>{const submitted=intakeLatest(r),c=submitted.content;if(c?.type!=='Research'||!reportMatch({due:c.due,programme:c.programme,planningMetadata:{}},reportFilters))return [];const a=intakeMentorLatest(r);return [{id:r.id,title:c.title,student:name(r.student),programme:c.programme,semester:c.semester||null,deadline:c.due,state:r.state,version:submitted.version,sourceCurrent:intakeSubmissionCurrent(r),mentor:a&&['REQUESTED','ACCEPTED','REASSIGNMENT_REQUESTED'].includes(a.state)&&intakeMentorCurrent(r,a)?name(a.mentor)+' · '+a.state:'No current intake mentor assignment',activityId:r.projectId||null}]});
 return {activities,requests};
}
function openResearchReport(){if(reportAccess()!=='institution')return toast('Research reporting is unavailable to this account.');reportDetail='research';go('Reports')}
function openResearchReportSource(kind,id){const s=researchReportSnapshot();if(!s)return toast('Research reporting access required.');if(kind==='activity'&&s.activities.some(p=>p.id===id)){const p=db.projects.find(p=>p.id===id);if(p&&canSee(p))return openProject(id)}if(kind==='intake'&&s.requests.some(r=>r.id===id)){const r=intakeRecord(id);if(r&&intakeVisible(r)){page='Activity Intake';selected=null;intakeFocus=id;return render()}}toast('This source is no longer available in the current research report scope.')}
function researchReportPage(s){
 const report=researchReportSnapshot();if(!report)return '';
 const assigned=assignedPublicationRows();
 return heading('Research activity summary','Reports overview → Submitted research requests / recorded activities → Permitted source detail',btn('All operational reports','openOperationalReports()'))+reportFilterForm()+`<div class="notice">Research means an explicit Research activity type or submitted Research intake type, never a keyword in a title, a supporting department or a publication category. Submitted requests and execution activities are separate records and are not added together. Research completion does not establish journal publication or website publication. Generated ${esc(eventTime(s.generated))}.</div><section class="panel"><h2>Submitted research requests</h2><p>${report.requests.length} visible submitted requests. Private unsubmitted drafts are excluded. The latest submitted snapshot supplies title/programme/semester/deadline; current draft edits are not copied. Intake academic year is not recorded, so a specific academic-year filter excludes these requests. Period basis: submitted requested activity deadline.</p>${tableHTML(['Request / submitted version','Student','Submitted programme / semester','Current intake state / source','Current mentor assignment','Requested deadline','Detail'],report.requests.map(r=>[esc(r.title)+'<br>'+esc(r.id)+' · v'+esc(r.version),esc(r.student),esc(r.programme)+'<br>'+esc(r.semester||'Semester not recorded'),esc(r.state)+'<br>'+(r.sourceCurrent?'Submitted source current':'Submitted source changed / historical'),esc(r.mentor),esc(r.deadline),btn('Open intake',esc('openResearchReportSource("intake",'+JSON.stringify(r.id)+')'))]))}${report.requests.length?'':'<p>No matching readable submitted Research intakes. This is not evidence of no institutional research.</p>'}</section><section class="panel"><h2>Recorded research activities</h2><p>${report.activities.length} distinct visible Research activities · ${report.activities.filter(p=>p.completed).length} completion-verified activities. Counts use activity IDs once.</p>${tableHTML(['Activity','Source programme / semester','Recorded mentor','Workflow / control','Deadline','Detail'],report.activities.map(p=>[esc(p.title)+'<br>'+esc(p.id),esc(p.programme)+'<br>'+esc(p.semester||'Semester not recorded'),esc(p.mentor),esc(p.state)+' · '+esc(p.control),esc(p.deadline),btn('Open activity',esc('openResearchReportSource("activity",'+JSON.stringify(p.id)+')'))]))}${report.activities.length?'':'<p>No matching visible activities explicitly typed Research. Research requests do not automatically create execution workspaces.</p>'}</section><section class="panel"><h2>Publication tracking access</h2><p>Publication requests remain private. General reporting access does not grant publication review or content access. Submission, nomination, editorial review, consent, approval, queued delivery and website acknowledgment remain distinct in the existing authorized tracking workflow. Real website delivery remains disabled.</p>${assigned.length?btn('Open my authorized publication tracking','openAssignedPublicationOverview()'):'<p>No current editorial/publishing tracking assignment is available to this account.</p>'}<p class="meta">This link uses existing current assignments and their own tracking scope; report period/programme filters do not expand or filter that separate workflow. It is not a research-publication total. No private text, feedback, CV information, grades or counseling records are copied into this report. Full research outputs, peer-reviewed journal indexing and institutional publication totals require their own approved source records.</p></section>`;
}

function finalizationReadinessPanel(){const p=srsReconciliation.finalizationCheckpoint;if(!p)return '';return `<section class="panel"><h2>Final prototype readiness checkpoint</h2><p><strong>${esc(p.status)}</strong></p><p>${esc(p.basis)}</p>${tableHTML(['Primary remaining gate','Open SRS gaps','Required evidence or decision'],p.groups.map(g=>[esc(g.lane),g.gaps.map(esc).join(', '),esc(g.required)]))}${srsReconciliation.automatedBaseline?`<p><strong>Latest automated baseline:</strong> ${esc(srsReconciliation.automatedBaseline.passed)} / ${esc(srsReconciliation.automatedBaseline.total)} check scripts passed at source ${esc(srsReconciliation.automatedBaseline.testedCommit||srsReconciliation.automatedBaseline.testedBaseCommit)} (candidate changes included). TypeScript passed. Browser/keyboard/PDF and institutional acceptance remain pending.</p>`:''}<h3>Bounded completion sequence</h3><ol>${p.acceptanceOrder.map(s=>'<li><strong>'+esc(s.work)+'</strong><p>'+esc(s.scope)+'</p></li>').join('')}</ol><p>${esc(p.manualAcceptance)}</p><p>${esc(p.productionBoundary)}</p><p>Next: ${esc(p.next)}</p></section>`}
